bool Read_GetUnitNanoPiecesResult(const WasmValue& input, GetUnitNanoPiecesResult& output, NativeCallStorage& storage, std::string& error)
{
	const auto* record = std::get_if<WasmValueRecord>(&input.storage);
	if (record == nullptr) { error = "Wasm argument is not a record"; return false; }
	const auto* value_pieces = FindRecordField(*record, "pieces", error);
	if (value_pieces == nullptr) return false;
	const auto* list_pieces = std::get_if<WasmValueList>(&(*value_pieces).storage);
	if (list_pieces == nullptr) { error = "Wasm argument is not a list"; return false; }
	auto& native_pieces = storage.Make<std::vector<std::int32_t>>();
	native_pieces.reserve(list_pieces->size());
	for (const auto& item : *list_pieces) {
		std::int32_t item_value{};
		if (!ReadScalar(item, item_value, error)) { return false; }
		native_pieces.push_back(std::move(item_value));
	}
	output.pieces = native_pieces.data();
	if (!AssignCount(list_pieces->size(), output.count, error)) { return false; }
	return true;
}

WasmValue Write_GetUnitNanoPiecesResult(const GetUnitNanoPiecesResult& value)
{
	WasmValueRecord fields;
	fields.emplace("pieces", WriteNativeList(value.pieces, value.count, [](const auto& value) { return WriteScalar(value); }));
	return WasmValue::Record(std::move(fields));
}

